  @CodeComments_Clear = 1,
  @CodeApprovalStatus = @CodeApprovalStatus_b6467477b45d,
  @CodeApprovalComments = @CodeApprovalComments_b6467477b45d,
  @CodeApprovalComments_Clear = 1,
  @CodeApprovedByUserID = @CodeApprovedByUserID_b6467477b45d,
  @CodeApprovedByUserID_Clear = 1,
  @CodeApprovedAt = @CodeApprovedAt_b6467477b45d,
  @CodeApprovedAt_Clear = 1,
  @CodeLocked = @CodeLocked_b6467477b45d,
  @ForceCodeGeneration = @ForceCodeGeneration_b6467477b45d,
